package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;
final class MaintenanceDialog {
 final MainActivity owner;final ReliabilityDialog ui;MaintenanceDialog(MainActivity c){owner=c;ui=new ReliabilityDialog(c);}
 void show(){new AlertDialog.Builder(owner).setTitle("日常操作・保守").setItems(new String[]{"処理状況をまとめて確認","更新前チェック","暗号化バックアップ・復元","容量・保存期間の目安","すべての記録を検索","直前の設定を元に戻す","会議の決定事項・担当・期限","条件付き転送予約","接続診断・復旧ガイド","文字・コントラスト・ショートカット"},(d,n)->{switch(n){case 0:status();break;case 1:preflight();break;case 2:new MaintenanceBackupUi(owner).show();break;case 3:capacity();break;case 4:search();break;case 5:ui.confirm("直前の対応設定を元に戻します。さらに変更済みの場合は上書きしません。",()->ui.post("profile-undo",ui.obj()));break;case 6:tasks();break;case 7:schedule();break;case 8:diagnosis();break;default:display();}}).setNegativeButton("閉じる",null).show();}
 void shortcut(){try{switch(DisplayPreferences.read(owner).getString("shortcut")){case "search":search();break;case "notes":ui.notes();break;case "tasks":tasks();break;default:status();}}catch(Exception e){show();}}
 void status(){ui.get("maintenance-status",v->{LinearLayout b=ui.box();ui.text(b,OperationOverviewDialog.describe(v));JSONObject schedule=v.optJSONObject("schedule");ui.text(b,"転送予約："+(schedule==null?"未設定":schedule.optString("state")+" / "+schedule.optString("reason")));ui.button(b,"要対応だけを見る",()->new ExperienceDialog(owner).attention());ui.button(b,"状態を更新",this::status);ui.button(b,"処理を中止する",ui::jobs);ui.button(b,"保存結果を照合",ui::storage);ui.button(b,"転送予約を確認",this::schedule);ui.display("統合処理状況",b);});}
 void preflight(){LokiUpdateDialog.show(owner);}
 void legacyPreflight(){ui.get("maintenance-preflight",v->{LinearLayout b=ui.box();ui.text(b,"このスマホの版："+v.optLong("phoneVersion")+"\n空き容量："+v.optLong("freeBytes")/1048576+" MiB\n署名SHA-256："+v.optJSONArray("signingSha256")+"\nグラス接続："+(v.optBoolean("glassFresh")?"最近の状態あり":"未確認")+"\n"+v.optString("message"));ui.button(b,"先にバックアップを作成",()->new MaintenanceBackupUi(owner).show());ui.button(b,"接続を切り分ける",this::diagnosis);ui.display("更新前の読み取りチェック",b);});}
 void capacity(){ui.get("maintenance-capacity",v->{LinearLayout b=ui.box();ui.text(b,"空き容量 "+v.optLong("freeBytes")/1048576+" MiB\n"+v.optString("message"));JSONArray rows=v.optJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(b,row.optString("title")+"："+(row.optBoolean("unavailable")?"未集計":row.optLong("bytes")/1048576+" MiB / "+row.optLong("files")+"ファイル"));}ui.text(b,"メモのごみ箱 "+v.optInt("noteTrash")+"件 / 案件のごみ箱 "+v.optInt("inboxTrash")+"件\n整理の目安："+v.optInt("retentionDays")+"日");for(int days:new int[]{7,30,90})ui.button(b,days+"日を整理の目安にする",()->ui.post("maintenance-retention",ui.with(ui.obj(),"days",days)));ui.button(b,"メモのごみ箱を選んで整理",ui::notes);ui.button(b,"案件のごみ箱を選んで整理",ui::inbox);ui.button(b,"写真一覧で確認",()->owner.startActivity(new Intent(owner,RecorderGalleryActivity.class)));ui.button(b,"会議一覧で確認",this::meetings);ui.button(b,"生成した画像・動画を確認",()->owner.openGeneratedRecords());ui.display("容量と記録の整理",b);});}
 void search(){LinearLayout b=ui.box();EditText query=ui.field(b,"検索語（複数語は空白区切り）","",160),from=ui.field(b,"開始日 YYYY-MM-DD（任意）","",10),until=ui.field(b,"終了日 YYYY-MM-DD（任意）","",10);Spinner type=new Spinner(owner);String[] kinds={"","memo","inbox","meeting","reading","photo","memory","task","conversation","continuation"};type.setAdapter(new ArrayAdapter<String>(owner,android.R.layout.simple_spinner_dropdown_item,new String[]{"すべて","メモ","受信箱","会議要約","読み取り","写真の説明","記憶","会議タスク","会話","会話の続き"}));b.addView(type);ui.button(b,"検索",()->{try{long first=from.getText().toString().trim().isEmpty()?0:java.time.LocalDate.parse(from.getText().toString()).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli(),last=until.getText().toString().trim().isEmpty()?Long.MAX_VALUE:java.time.LocalDate.parse(until.getText().toString()).plusDays(1).atStartOfDay(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli()-1;ui.get("maintenance-search",ui.params("q",query.getText().toString(),"type",kinds[type.getSelectedItemPosition()],"from",""+first,"until",""+last),v->{LinearLayout result=ui.box();ui.text(result,v.optString("scope")+"\n一致 "+v.optInt("matched")+"件\n制限・未取得："+v.optJSONArray("issues"));JSONArray rows=v.optJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.button(result,row.optString("type")+" / "+row.optString("title"),()->{ExperienceDialog.openRecord(owner,row);});}ui.display("検索結果",result);});}catch(Exception e){ui.confirm("日付をYYYY-MM-DDで入力してください",()->{});}});ui.display("全記録の横断検索",b);}
 void meetings(){ui.work(()->new JSONObject().put("items",MeetingAudioStore.list(owner)),v->{LinearLayout b=ui.box();JSONArray rows=v.optJSONArray("items");for(int i=0;i<Math.min(100,rows.length());i++){JSONObject row=rows.optJSONObject(i);ui.button(b,row.optString("title","会議")+" / "+row.optString("id"),()->{LinearLayout detail=ui.box();ui.button(detail,"会議記録を開く",()->MeetingReviewDialog.show(owner,row.optString("id")));ui.button(detail,"決定事項・担当・期限を確認",()->candidates(row.optString("id")));ui.display("会議",detail);});}ui.display("直近100件の会議",b);});}
 void tasks(){ui.get("maintenance-tasks",v->{LinearLayout b=ui.box();JSONArray rows=v.optJSONArray("items");ui.text(b,"会議タスク "+rows.length()+"件");if(rows.length()==0)ui.text(b,"まだタスクはありません。会議の要約から候補を確認して追加できます。");ui.button(b,"会議から候補を確認",this::meetings);ui.text(b,"確認して保存したタスクです。担当・期限は入力した値を使います。");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(b,(row.optString("state").equals("done")?"完了：":"未完了：")+row.optString("title")+"\n担当："+row.optString("assignee","未指定")+" / 期限："+row.optString("due","未指定")+"\n出典："+row.optString("excerpt"));ui.button(b,"本文・担当・期限を編集／履歴",()->new ExperienceDialog(owner).editTask(row));String next=row.optString("state").equals("done")?"pending":"done";ui.button(b,next.equals("done")?"完了にする":"未完了に戻す",()->ui.work(()->MeetingTaskBoard.change(owner,row.getString("id"),row.getInt("revision"),next),changed->{LinearLayout undo=ui.box();ui.text(undo,"状態を保存しました");ui.button(undo,"元に戻す",()->ui.work(()->MeetingTaskBoard.change(owner,changed.getString("id"),changed.getInt("revision"),next.equals("done")?"pending":"done"),ignored->tasks()));ui.display("タスクの状態変更",undo);}));if(row.optString("state").equals("done"))ui.button(b,"この完了タスクを完全削除",()->ui.confirm("出典への参照を含めこのタスクを削除します。取り消せません。会議原本は保持します。",()->ui.post("maintenance-task-change",ui.with(ui.with(ui.with(ui.obj(),"id",row.optString("id")),"revision",row.optInt("revision")),"state","remove"))));}ui.display("会議のタスク",b);});}
 void candidates(String id){ui.get("maintenance-candidates",ui.params("id",id),v->{LinearLayout b=ui.box();ui.text(b,"要約の候補です。正確性を原記録で確認してください。担当と期限は推測せず空欄にしています。");JSONArray rows=v.optJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);EditText title=ui.field(b,"確認した内容",row.optString("text"),800),person=ui.field(b,"担当（任意）","",120),due=ui.field(b,"期限 YYYY-MM-DD（任意）","",10);ui.button(b,"確認した内容をタスク保存",()->ui.confirm(title.getText()+"\n担当："+person.getText()+" / 期限："+due.getText()+"\nローカルタスクとして保存します。",()->ui.post("maintenance-task-save",ui.with(ui.with(ui.with(ui.with(ui.with(ui.with(ui.obj(),"meetingId",id),"sourceHash",v.optString("sourceHash")),"index",row.optInt("index")),"title",title.getText().toString()),"assignee",person.getText().toString()),"due",due.getText().toString()))));}ui.display("決定事項・担当・期限",b);});}
 void schedule(){ui.get("maintenance-schedule",v->{LinearLayout b=ui.box();ui.button(b,v.optBoolean("notificationsEnabled")?"予約結果の端末通知をOFF":"予約結果の端末通知をON（音なし）",()->ui.post("maintenance-schedule-notifications",ui.with(ui.obj(),"enabled",!v.optBoolean("notificationsEnabled"))));ui.text(b,"端末通知："+(v.optBoolean("notificationsEnabled")?"ON":"OFF")+" / Androidの通知許可："+(v.optBoolean("notificationsAvailable")?"有効":"未許可・表示できない可能性")+"。許可要求や音声再生は行いません。");ui.text(b,"スマホの充電・Wi-Fi・新しいグラス接続を条件に、選んだ転送を一度だけ送信待ちに追加します。6時間で期限切れ。スマホのロキ稼働中に30秒ごとに確認。録音・撮影は開始も停止もしません。グラスで記録中なら転送できません。\n現在："+v.optString("state","未設定")+" / "+v.optString("reason"));if(v.optString("state").equals("waiting")){ui.button(b,"この予約を中止",()->ui.post("maintenance-schedule-cancel",ui.with(ui.obj(),"id",v.optString("id"))));ui.button(b,"充電・Wi-Fi条件を外して今すぐ送信",()->ui.confirm("通信料が発生する可能性があります。転送予約を一度だけ送信待ちへ追加します。",()->ui.post("maintenance-schedule-run",ui.with(ui.obj(),"id",v.optString("id")))));}else if(v.optString("state").matches("dispatch-unconfirmed|queued-unconfirmed|remote-active")){ui.text(b,"この予約の結果を確認中です。新しい予約はまだ作成できません。保存照合と状態更新で確認してください。");}else{CheckBox charge=new CheckBox(owner),wifi=new CheckBox(owner);charge.setText("スマホが充電中");wifi.setText("スマホがWi-Fi接続中");charge.setChecked(true);wifi.setChecked(true);b.addView(charge);b.addView(wifi);for(String kind:new String[]{"photo","meeting"})ui.button(b,kind.equals("photo")?"写真転送を予約":"会議録音転送を予約",()->ui.confirm("表示した条件で6時間以内に一度だけ転送を要求します。未確認でも自動再送しません。",()->ui.post("maintenance-schedule-save",ui.with(ui.with(ui.with(ui.obj(),"kind",kind),"charging",charge.isChecked()),"wifi",wifi.isChecked()))));}ui.button(b,"状態を更新",this::schedule);ui.display("条件付き転送",b);});}
 void diagnosis(){ui.get("maintenance-diagnosis",v->{LinearLayout b=ui.box();JSONArray rows=v.optJSONArray("steps");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.text(b,(i+1)+". "+row.optString("title")+"\n"+row.optString("state")+"\n"+row.optString("action"));}ui.button(b,"Androidの回線設定",()->owner.startActivity(new Intent(android.provider.Settings.ACTION_WIRELESS_SETTINGS)));ui.button(b,"Bluetooth設定",()->owner.startActivity(new Intent(android.provider.Settings.ACTION_BLUETOOTH_SETTINGS)));ui.button(b,"ローカル動作チェック",()->{LocalHealthCheck.start(owner,true);status();});ui.button(b,"接続ごとの権限を確認",ui::sessions);ui.button(b,"もう一度診断",this::diagnosis);ui.display("接続の切り分け",b);});}
 void display(){ui.get("maintenance-display",v->{LinearLayout b=ui.box();ui.text(b,"この保守画面・保存履歴画面の表示を調整します。Android本体の文字倍率は変更しません。");Spinner size=new Spinner(owner),shortcut=new Spinner(owner);size.setAdapter(new ArrayAdapter<String>(owner,android.R.layout.simple_spinner_dropdown_item,new String[]{"標準 16sp","大きい 20sp","特大 24sp"}));size.setSelection(v.optInt("size")==16?0:v.optInt("size")==24?2:1);shortcut.setAdapter(new ArrayAdapter<String>(owner,android.R.layout.simple_spinner_dropdown_item,new String[]{"処理状況","横断検索","メモ","会議タスク"}));String[] keys={"status","search","notes","tasks"};for(int i=0;i<keys.length;i++)if(keys[i].equals(v.optString("shortcut")))shortcut.setSelection(i);CheckBox contrast=new CheckBox(owner);contrast.setText("高コントラスト（白文字・黒背景）");contrast.setChecked(v.optBoolean("contrast"));b.addView(size);b.addView(contrast);b.addView(shortcut);ui.button(b,"表示設定を保存",()->ui.post("maintenance-display-save",ui.with(ui.with(ui.with(ui.obj(),"size",new int[]{16,20,24}[size.getSelectedItemPosition()]),"contrast",contrast.isChecked()),"shortcut",keys[shortcut.getSelectedItemPosition()])));ui.display("表示とショートカット",b);});}
}
